{
  "findings": [
    {
      "ref": "[R292]",
      "area": "contact",
      "claim": "A parent reports no instructions on what to do and confusion about flashing blue tiles and poles.",
      "stance": "risk",
      "quote": "Why isn’t there any instructions on what to do?Am I supposed to magically know what to build without a picture to work off of? What’s the purpose of of the flashing blue tiles on the left side...other being distracting? What are the poles on the sides for?"
    },
    {
      "ref": "[R312]",
      "area": "contact",
      "claim": "A parent reports the game is unplayable without camera control.",
      "stance": "risk",
      "quote": "This would be a great game if you could change the camera."
    },
    {
      "ref": "[R313]",
      "area": "contact",
      "claim": "A parent reports the controls cause pieces to bounce and are hard to place quickly.",
      "stance": "risk",
      "quote": "Are the worst. Parts require quick placement but the block bounces all around where you try to place it."
    },
    {
      "ref": "[R333]",
      "area": "contact",
      "claim": "A parent reports the camera automatically drifts back to default when picking up a piece, preventing placement behind other pieces.",
      "stance": "risk",
      "quote": "The game has promise, but the camera angle automatically drifts back to the default angle when you pick up a piece. You can't place a piece behind another piece due to this. You basically have to start over to work with the default camera angle. This is annoying."
    },
    {
      "ref": "[R280]",
      "area": "age_gating",
      "claim": "A parent reports the game is too hard for a 6-year-old daughter despite the stated age range.",
      "stance": "neutral",
      "quote": "I do like the functionality for myself to play. The game is way to frustrating and hard for my 6yo daughter though. With my help we beat the game in about 45 minutes."
    },
